INSERT INTO public.equipment VALUES ('62d57f1e-cf21-4343-bd6b-86b90dd02e28', 'Life Fitness E5 Cross Trainer Elliptical Exercise Machine with Go Console, Titanium', 'elliptical', 'The E5 Adjustable-Strike Elliptical Cross-Trainer is a versatile home exercise machine for effective total-body workouts. The stride adjusts from 18" to 24" with the push of a button and multigrip handles let exercisers work different muscle groups. The smooth and natural feeling ellipse path of the E5 Cross-Trainer is based on years of biomechanics research. The E5 Adjustable-Stride Elliptical Cross-Trainer has an adjustable stride and several other features that create effective low-impact, total-body workouts tailored to fit any exerciser.', 'Life Fitness', 'Life Fitness E5 Cross Trainer Elliptical', 'Titanium', 'Aluminum');
