INSERT INTO public.equipment VALUES ('64865a5f-55d4-49f6-aec3-c7c725c51354', 'Precor EFX 833 Commercial Series Elliptical Fitness Crosstrainer', 'elliptical', 'Bring home the exact EFX 833 used in fitness clubs worldwide. The EFX is self-powered, with adjustable CrossRamp angles from 13 to 40 degrees, moving handlebars, 10 preset workouts, 20 resistance levels and touch and telemetry heart rate monitoring with Smart Rate . The preset workouts and resistance levels help you tailor your workout to your fitness goals and stay challenged. And adding variety to your workouts helps avoid plateauing', 'Precor', 'EFX 833', 'black, silver', 'Polypropylene (PP), Polyurethane, Stainless Steel');
