INSERT INTO public.equipment VALUES ('0caff5e6-816c-4b69-8b6a-94ea12b8ea50', 'MERACH Under Desk Elliptical, Ellipse Leg Exerciser Electric as Seen on TV for Seniors with Remote Control & 12 Adjustable Speeds, Quiet Portable Seated Pedal Exerciser Machine for Home', 'elliptical', '', 'MERACH', 'MR-E32', 'Black', 'Alloy Steel');
INSERT INTO public.equipment VALUES ('c30069c5-d596-4c74-8f8f-71adc431c437', 'Teeter FreeStep Recumbent Cross Trainer Stepper, Zero-Impact Exercise Bike Alternative w/Patented Physical Therapy Stride, Up to 350lb, Free App w/Trainer Workouts', 'elliptical', 'Set yourself free with the Teeter FreeStep for the ultimate full-body workout, free from joint pain. The FreeStep is the only home-use stepper with patented physical therapy technology, for a natural stepping motion that eases join strain. 93% of users surveyed reported the FreeStep is easier on their knees and back than other cardio options. Dual power motion engages both the upper and lower body, distributing muscle exertion to avoid burn out and make exercise feel easier. Proven to burn 17.4% more calories than a recumbent bike, the FreeStep delivers a superior cardio workout while incorporating full-body resistance training to develop muscle strength throughout the whole body. The LT1 delivers a premium, low-impact exercise experience with 13 levels of magnetic resistance, easy-reach water bottle holder, and convenient transport wheels, all within a low-profile footprint and a 300 lb user rating. The LT3 offers a step up with UltraGlide Bearings with long-lasting frictionless motion, SoftStep Pedals with durable grip surface, larger ComfortSelect Seat, and durable SureGrip Handles. The LT7 upgrades your workout experience with 20-level quick-key magnetic resistance, a 9" color LCD screen with 21 pre-programmed, goal-based workouts, HRM compatibility, and extra-large seat with more positioning options. Convenient features include an electronic Step Lock for easier entry and exit, dual cup holders and transport wheels - topped off with an increased 350 lb user rating. Inspire motivation with the FREE Teeter Move app. Access a huge variety of trainer-led workouts designed for all fitness levels, on demand, no subscription needed!', 'Teeter', 'Teeter FreeStep Recumbent Cross Trainer Stepper, Zero-Impact Exercise Bike Alternative w/Patented Physical Therapy Stride, Up to 350lb, Free App w/Trainer Workouts', 'Black', 'Alloy Steel');
INSERT INTO public.equipment VALUES ('887875b7-9c48-40ff-809a-4d522cd9b8ff', 'Precor EFX 546i Commercial Series Elliptical Fitness Crosstrainer (2009 Model) (Renewed)', 'elliptical', 'SHIPPING WEIGHT 400 LBS FREE PICK UP $ 175 WITH IN 100 MILES OF BETHPAGE, NY WITH IN US CONTINETAL + $ 400.00 SHIPPING DIFFERENCE WILL BE REFUNDED FOR FREE PICK UP AND 100 MILES DISTANCE CUSTOMERS.', 'Precor', 'EFX 546i Version 4 New Body Style', 'Black', 'Alloy Steel');
