INSERT INTO public.equipment VALUES ('c36d0247-a5bc-42c1-b84e-f160238dd7d8', 'Exerpeutic 400 Lb. Capacity Heavy-Duty Walking/Jogging Exercise Treadmill - Home Gym Workout Equipment - Foldable Under Desk Design', 'treadmill', 'This heavy duty treadmill is perfect for those who want a compact, affordable and high quality 400 pound weight capacity treadmill. Specially designed and tested to 400 pounds weight capacity, it can help you reach your fitness goals. Perfect for home office, living room or in office use, it fits under any desk; making it your ideal desk treadmill solution. The walking area is also larger than most other treadmills at 16 x 40 inches.', 'Exerpeutic', 'SuperMax 2-in-1 Treadmill', 'Black and Blue', 'Alloy Steel, Plastic');
