INSERT INTO public.equipment VALUES ('c7714a59-9911-402a-8e2b-5e448e60c40e', 'Hydrow Pro Rowing Machine with Immersive 22" HD Rotating Screen - Stows Upright | Live and On-Demand at-Home Workouts, Membership Required', 'chess press machine', 'Working out at home is a whole lot more exciting when you’re transported to, say, a Scandinavian fjord. Hydrow’s immersive experience takes you all around the world for full-body workouts – over 5,000, to be exact – led by world-class Athletes in stunning destinations. With a proprietary computer-controlled electromagnetic drag mechanism designed to mimic the feel of rowing on water, getting onto the Hydrow Pro feels about as close as it gets to really getting out there.', 'Hydrow', 'Hydrow Rower', 'Black/ Silver', 'Aluminum');
