INSERT INTO public.equipment VALUES ('507e9fce-269a-4f0f-893a-672f503b37ea', 'Valor Fitness DG-1 Stationary Upright Weight Bench-Tripod Base- Max Weight 750 lb- Heavy Duty Weightlifting Equipment-Shoulders Arms Bicep Triceps Workout- Commercial or Home Gym Use', 'shoulder press machine', '', 'Valor Fitness', 'DG-1', 'Silver', 'Alloy Steel');
INSERT INTO public.equipment VALUES ('7011623f-84f0-44cc-a94d-9d52e5828de7', 'Soozier Chest Fly Machine and Chest Press Station, Delt Machine Home Gym Equipment for Chest, Back, Pectoral, Rear Deltoid and Shoulder Training', 'shoulder press machine', 'Description:Transform your workout routine with the Soozier chest fly machine! This versatile chest press machine features an adjustable 4-level seat and resistance up to 132 lbs, which is great for any home gym. Crafted for stability and various upper body exercises, it''s a must-have for those serious about strength training. Step up your fitness game with this essential home workout equipment.Features:● Chest press and butterfly machine target upper body muscles● Seat adjusts to four levels, enhancing comfort during workouts● Adjustable resistance fits 1" opening weight plates up to 132 lbs (weight is not included)● 2" x 2" steel tube construction for enhanced durability● Anti-slip foot bases ensure stability and safety while exercisingSpecifications:● Color: Red● Materials: Steel, PU● Overall Dimensions: 38.6" L x 43.3" W x 78.1" H● Seat Size: 11.8" L x 11" W x 20.9" -23.8" H● Back Size: 25.2" L x 11" W● Butterfly Arm Spacing: 28.7" W● Max Counterweight: 66 lbs. for a side, 132 lbs. in total● Weight Capacity: 265 lbs.● Item Label: A91-366V00RDPackage Includes:- 1 x Chest Workout Station- 1 x Manual', 'Soozier', 'Power Tower', 'Yellow', 'Alloy Steel, Polyurethane');
