INSERT INTO public.equipment VALUES ('43001ad0-ecc9-416b-bbe5-d810b056141d', 'PASYOU Air Magnetic Rowing Machine for Home 10-Level Resistance 350lb Load Rower Machine Foldable Commercial Row Machines with 47in Rail and Bluetooth Backlit Monitor, Adjustable Device Holder PR70', 'rowing machine', '', 'PASYOU', 'PR70', 'BLACK', 'Alloy Steel');
INSERT INTO public.equipment VALUES ('2c4609a8-04f5-4923-8eba-9a011f71c226', 'YSSOA Rowing Machine Rower Ergometer, with 12 Levels of Adjustable Resistance, Digital Monitor and 260 lbs of Maximum Load Black', 'rowing machine', 'The household folding rowing device can meet your indoor fitness needs. Each rowing exercise can exercise more than 80% of the muscles of the whole body. It is very suitable for rehabilitation, weight loss, body shaping, strength training, etc. The 12-level adjustable tension meets the needs of different exercises, the console detects your exercise progress in real time, and the fully padded seat and non-slip foot pedals increase the comfort and safety of your exercise.', 'YSSOA', 'Fitness Rowing Machine', 'Black', 'Aluminum Frame');
INSERT INTO public.equipment VALUES ('78f0b0ae-2aac-4e35-a092-f6c4ea5206be', 'Aviron StrongGo Rowing Machine -Compatible with iPad—Dual Air & Magnetic Resistance Up to 100 lbs | Game-Based Workouts, Compact Storage Design', 'rowing machine', 'The Aviron StrongGo rowing machine redefines at-home workouts! Compatible with your iPad, the StrongGo seamlessly delivers a truly unique fitness entertainment experience. Designed for all fitness levels and body types, it features dual air and magnetic resistance of up to 100 lbs. Enjoy a blend of full-body strength and cardio workouts and immersive programs that use game psychology to make every workout fun and addictive. Why settle for boring when you can have games, coached workouts, scenic rowing and so much more—all in a compact, sleek design for easy storage. *Compatible with iPad, not included', 'Aviron', 'Aviron StrongGo Rower', 'Black', 'Alloy Steel, Aluminum');
INSERT INTO public.equipment VALUES ('40dfa026-00b0-4c49-9253-e9cfc83c565c', 'WaterRower M1 Hi Rise Rowing Machine with S4 Monitor | USA Made | Original Handcrafted Erg Machine for Home Use & Gym | Best Warranty', 'rowing machine', '', 'WaterRower', 'M1 HiRise', 'Silver', 'Aluminum');
INSERT INTO public.equipment VALUES ('c0f998f5-521c-4f11-8048-7ad1fabdf6bc', 'Aviron Strong Series Rower: 22"" HD Touchscreen, Dual Air & Magnetic Resistance up to 100 lbs. Game-Based Workouts, Streaming, Compact Design, Black', 'rowing machine', 'The Aviron Strong Series Rower redefines at-home workouts, using its 22" HD touchscreen to deliver a truly unique fitness entertainment experience. Designed for all fitness levels and body types, it features dual air and magnetic resistance of up to 100 lbs. Enjoy a blend of full-body strength and cardio workouts and immersive programs that use game psychology to make every workout fun and addictive. Why settle for boring when you can have games, coached workouts, scenic rowing, access to your favorites streaming services and so much more—all in a compact, sleek design for easy storage.', 'Aviron', 'Strong Series Rower', 'Black', 'Aluminum, Alloy Steel');
