INSERT INTO public.equipment VALUES ('3247bc05-fda3-413d-9478-ae1c0157a3e6', 'SNODE Rowing Machine for Home Use, Rower with LCD Monitor, Ergonomic Seat, Dual Rail, HIgh Weight Capacity', 'rowing machine', 'The SNODE Rowing Machine is the perfect addition to your home gym, offering a full-body workout that targets multiple muscle groups. With its sturdy dual rail design and ergonomic seat, you can enjoy a smooth and comfortable rowing experience. The LCD monitor tracks your progress, displaying metrics like time, distance, and calories burned. This rower accommodates users up to 350 lbs, making it suitable for various fitness levels. Bring the benefits of rowing into your home and elevate your fitness routine with the SNODE Rowing Machine.', 'snode', 'snode rowing machine', 'black', 'Alloy Steel');
