INSERT INTO public.equipment_features VALUES ('9b6c8cd7-35ae-4d93-b261-15b7462e024e', 'bfc0fec6-de54-44b3-bb16-cf096ebafbc2', 'Premium Material: Our lat pull down bar provides additional strength and durability to your workout routine. Constructed with solid steel, our lat bar is far more heavy-duty than plastic or wooden lat bars. It is designed to have a strong grip, allowing for maximum muscle activation during your lat pull down routine.');
INSERT INTO public.equipment_features VALUES ('31267736-4236-4fd3-82ac-f34564605f6d', 'c4004570-c898-4446-8b29-a5d61dbbd6a1', 'Height Adjustable: This bicep curl bench features a 4-position adjustable armrest (33.5"-40.2"), a 5-position adjustable seat (18.1"-21.7"), and a 5-position adjustable barbell rack (22.8"-30.7"), accommodating various body types and heights.');
