INSERT INTO public.equipment_features VALUES ('e53224b8-6443-46bb-8f41-cbf997c681a4', 'c4004570-c898-4446-8b29-a5d61dbbd6a1', 'Strong Structure: Our bicep tricep curl machine supports a max load of 265 pounds and is constructed with solid steel tubing and non-slip foot covers, ensuring longevity and stability.');
INSERT INTO public.equipment_features VALUES ('6cd7e291-975e-49af-b39a-8d61aa26fc32', 'c4004570-c898-4446-8b29-a5d61dbbd6a1', 'Versatile Workouts: Suitable for both dumbbell and barbell biceps routines, this bicep machine is great for enhancing your arm workouts and building strength in your biceps and triceps.');
INSERT INTO public.equipment_features VALUES ('54144996-6d5f-4dba-b777-5dc1606cc37d', 'c4004570-c898-4446-8b29-a5d61dbbd6a1', 'Tricep Machine Information: Overall dimensions: 35.4" L x 25.2" W x 33.5"-40.2" H. Supports up to 265 lbs. Easy to assemble.');
