INSERT INTO public.equipment_features VALUES ('0aa7ffc2-3450-498a-bafe-8d9879748f15', '051a1034-470c-4027-98a5-fea0b6000bbc', 'Compatible with 1-Inch and 2-Inch Plates, Perfect for Comprehensive Leg Workouts The Tib Bar seamlessly fits both 1-inch and 2-inch weight plates, making it an essential piece of equipment for your leg and tibialis training. It''s great for performing tib raises, calf extensions, and strengthening your ankle and shin muscles—ideal for home or gym use.');
