INSERT INTO public.equipment_features VALUES ('72792968-b64c-4d56-962d-432e265cb668', '9512f30b-9135-4ac1-8f5c-941c0c4d71ae', 'Professional Gym Handle for Cable：Our exercise handles are suitable for professionals and beginners to do muscle building, fat loss, and strength training. Also suitable for home gym lat pull-down cable machines, weight pulley systems and Smith machines.');
