INSERT INTO public.equipment_features VALUES ('60600144-b3cb-44f0-a5d1-7a41b15d33bd', '3e51c461-2715-4a71-965d-aa71ef4f8b95', 'Incomparable Load-Bearing Capacity: Push your limits with confidence! Our pull down handles support up to 280kg (620 lbs), top solid welding D-rings built for the most intense workouts. The heavy-duty construction guarantees safety and durability, letting you focus entirely on achieving your fitness goals.');
INSERT INTO public.equipment_features VALUES ('3334ac1b-2439-4093-b3b7-54243a5f99a7', '3e51c461-2715-4a71-965d-aa71ef4f8b95', 'Versatile Equipment Compatibility: Exercise handles can serve as a suitable replacement for worn-out handles on your fitness equipment. Whether you have a home gym, weight pulley and cable machines, pilates reformers, functional training equipment, a chair gym or even a smith machine, cable machines handles can perfevt match with your setup.');
