INSERT INTO public.equipment_features VALUES ('f68630ef-4b96-466f-90f4-2c22679cb5b7', '3e51c461-2715-4a71-965d-aa71ef4f8b95', '12 Months 100% Satisfaction Guaranted: your satisfaction more than anything else. we will provide you with a 1-year warranty and a 90-day refund service. If you have any problems during the use, not satisfied with our exercise handles or services, please contact us by email. We will answer your questions within 24 hours.');
