INSERT INTO public.equipment_features VALUES ('b0782d5e-d8d3-409e-9ce5-f8e9e4db32b6', 'b1e0868f-aa15-472c-8620-bfdffeccd653', 'FEATURES - This barbell has a recommended weight capacity of 150 lbs. Threaded ends with star lock collars to securely hold weights; durable black powder coat finish');
INSERT INTO public.equipment_features VALUES ('9356b16e-b460-48c4-a06c-41509911a617', 'b1e0868f-aa15-472c-8620-bfdffeccd653', 'TRUST - Trust experience. CAP has been a pioneer in the fitness industry for over 30 years with locations worldwide. Chances are, if you have ever worked out before you have used a CAP product.');
