INSERT INTO public.equipment_features VALUES ('cd55f4cf-20e2-4eaa-9e00-b6e9f30b0649', 'db2d0fca-a248-42d7-ac47-7c285c724604', 'Set includes – 52. 5 lbs. Total: one 17” dumbbell handle, two 1. 25-Pound plates, two 2. 5-Pound plates, eight 5-pound plates, and two star-lock collars.');
INSERT INTO public.equipment_features VALUES ('cffae17f-1eb5-4c4a-a1b1-8f4ad6176b47', 'db2d0fca-a248-42d7-ac47-7c285c724604', 'Cast iron weight plates fit 1-inch standard handles and bars – plates will accommodate all standard 1-inch handles and bars. High-grade cast iron plates covered with black epoxy finish prevent rust and corrosion for long-lasting performance.');
INSERT INTO public.equipment_features VALUES ('b02a2450-4229-4eab-8c96-ef7805bc2682', 'db2d0fca-a248-42d7-ac47-7c285c724604', '17-Inch diamond knurled chrome handle – crafted from cold rolled steel with medium-depth diamond knurling for a secure, firm and non-slip grip.');
INSERT INTO public.equipment_features VALUES ('9f65b417-1ca4-4429-945b-e329f4ae7b1f', 'db2d0fca-a248-42d7-ac47-7c285c724604', 'Star-lock collars with rubber O-rings – course thread star-lock collars are easy to tighten and loosen on threaded ends and helps keep weight plates securely fashioned while weightlifting.');
INSERT INTO public.equipment_features VALUES ('c7e65da7-e34b-4ecd-9084-6a8b31309eb1', 'db2d0fca-a248-42d7-ac47-7c285c724604', 'Easy use & storage – compact, convenient, and easy to use and store. This all-in-one dumbbell set eliminates the need for multiple dumbbells in your home gym. Great for targeting Individual muscle groups or incorporating into a full body workout.');
